import{_ as o,a0 as l,w as p,s as r,I as t,x as e,a1 as a,A as i,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"我在源碼控制中維護點文件的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"我在源碼控制中維護點文件的技巧 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我在源碼控制中維護點文件的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我在源碼控制中維護點文件的技巧 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220208 My tips for maintaining dotfiles in source control","title":"我在源碼控制中維護點文件的技巧","tag":"202202","desc":""},"relativePath":"202202/20220208 My tips for maintaining dotfiles in source control.md","filePath":"[post].md"}'),u={name:"202202/20220208 My tips for maintaining dotfiles in source control.md"};function f(g,s,m,h,c,b){const n=l("Link");return p(),r("div",null,[s[18]||(s[18]=t("h1",{id:"我在源碼控制中維護點文件的技巧",tabindex:"-1"},[e("我在源碼控制中維護點文件的技巧 "),t("a",{class:"header-anchor",href:"#我在源碼控制中維護點文件的技巧","aria-label":"Permalink to “我在源碼控制中維護點文件的技巧”"},"​")],-1)),s[19]||(s[19]=t("blockquote",null,[t("p",null,"當你把環境保持在源碼控制中，開發虛擬機和容器就成了一個解決方案，而不是一個問題。")],-1)),s[20]||(s[20]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202202/18/145014pc7lmh5ts15mm0tm.jpg",alt:""})],-1)),s[21]||(s[21]=t("p",null,[e("你是否曾經開始使用一台新的電腦，不管是出於自願還是因為舊的電腦讓你的魔法煙消雲散，並且對花了多長時間才把所有東西都 "),t("em",null,"弄好"),e(" 而感到沮喪？更糟糕的是，有沒有花了一些時間重新配置你的 shell 提示符，然後意識到你更喜歡以前的樣子？")],-1)),t("p",null,[s[1]||(s[1]=e("對我來説，當我決定要在 ",-1)),a(n,{href:"https://opensource.com/tags/containers"},{default:i(()=>[...s[0]||(s[0]=[e("容器",-1)])]),_:1}),s[2]||(s[2]=e(" 中進行開發時，這個問題就變得很嚴重了。容器是非持久的。開發工具很容易解決：一個帶有工具的容器鏡像就可以工作。源碼很容易解決：源碼控制維護它，開發是在分支上。但是，如果每次我創建一個容器，我都需要仔細地配置它，這就太痛苦了。",-1))]),s[22]||(s[22]=d(`<h3 id="主目錄的版本控制" tabindex="-1">主目錄的版本控制 <a class="header-anchor" href="#主目錄的版本控制" aria-label="Permalink to “主目錄的版本控制”">​</a></h3><p>將配置文件保存在版本控制中一直是一個有吸引力的選擇。但是天真地這麼做是令人擔憂的。不可能直接對 <code>~</code> 進行版本控制。</p><p>首先，太多的程序認為把秘密放在那裏是安全的。此外，它也是 <code>~/Downloads</code> 和 <code>~/Pictures</code> 等文件夾的位置，這些文件夾可能不應該被版本化。</p><p>小心翼翼地在主目錄下保留一個 <code>.gitignore</code> 文件來管理 <code>include</code> 和 <code>exclude</code> 列表是有風險的。在某些時候，其中一個路徑會出錯，花費了幾個小時的配置會丟失，大文件會出現在 Git 歷史記錄中，或者最糟糕的是，秘密和密碼會被泄露。當這一策略失敗時，它就成了災難性的失敗。</p><p>手動維護大量的符號鏈接也是行不通的。版本控制的全部原因是為了避免手動維護配置。</p><h3 id="寫一個安裝腳本" tabindex="-1">寫一個安裝腳本 <a class="header-anchor" href="#寫一個安裝腳本" aria-label="Permalink to “寫一個安裝腳本”">​</a></h3><p>這暗示了在源碼控制中維護點文件的第一條線索：寫一個安裝腳本。</p><p>就像所有好的安裝腳本一樣，讓它 <em>冪等</em>：運行兩次不會兩次增加配置。</p><p>像所有好的安裝腳本一樣，讓它 <em>只做最少的事情</em>：使用其他的技巧來指向你的源碼控制中的配置文件。</p><h3 id="config-目錄" tabindex="-1">~/.config 目錄 <a class="header-anchor" href="#config-目錄" aria-label="Permalink to “~/.config 目錄”">​</a></h3><p>現代 Linux 程序在直接在主目錄中尋找配置之前，會先在 <code>~/.config</code> 中尋找。最重要的例子是 <code>git</code>，它在 <code>~/.config/git</code> 中尋找。</p><p>這意味着安裝腳本可以將 <code>~/.config</code> 符號鏈接到主目錄中源碼控制的管理目錄中的一個目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>set -e</span></span>
<span class="line"><span>DOTFILES=&quot;$(dirname $(realpath $0))&quot;</span></span>
<span class="line"><span>[ -L ~/.config ] || ln -s $DOTFILES/config ~/.config</span></span></code></pre></div><p>此腳本尋找它的位置，然後將 <code>~/.config</code> 鏈接到它被簽出的地方。這意味着幾乎沒有關於它需要位於主目錄中的位置的假設。</p><h3 id="獲取文件" tabindex="-1">獲取文件 <a class="header-anchor" href="#獲取文件" aria-label="Permalink to “獲取文件”">​</a></h3><p>大多數 shells 仍然直接在主目錄下尋找文件。為了解決這個問題，你要增加一層指示。從 <code>$DOTFILES</code> 中獲取文件意味着在修改 shell 配置時不需要重新運行安裝程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$!/bin/bash</span></span>
<span class="line"><span>set -e</span></span>
<span class="line"><span>DOTFILES=&quot;$(dirname $(realpath $0))&quot;</span></span>
<span class="line"><span>grep -q &#39;SETTING UP BASH&#39; ~/.bashrc || \\</span></span>
<span class="line"><span>  echo &quot;source $DOTFILES/starship.bash # SETTING UP BASH&quot; &gt;&gt; ~/.bashrc</span></span></code></pre></div><p>再次注意，這個腳本很仔細地做了冪等：如果這一行已經在那裏了，它就不會再添加。它還考慮到了你在 <code>.bashrc</code> 上已經做的任何編輯，雖然這不是一個好主意，但也沒有必要懲罰它。</p><h3 id="反覆測試" tabindex="-1">反覆測試 <a class="header-anchor" href="#反覆測試" aria-label="Permalink to “反覆測試”">​</a></h3><p>當你把環境保持在源碼控制中時，開發虛擬機和容器就成了一個解決方案，而不是一個問題。試着做一個實驗。建立一個新的開發環境，克隆你的點文件，安裝，並看看有什麼問題。</p><p>不要只做一次。至少每週做一次。這將使你更快地完成工作，同時也會告訴你什麼是不可行的。暴露問題，修復它們，然後重複。</p><hr>`,22)),t("p",null,[s[4]||(s[4]=e("via: ",-1)),a(n,{href:"https://opensource.com/article/22/2/dotfiles-source-control"},{default:i(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/22/2/dotfiles-source-control",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/moshez"},{default:i(()=>[...s[5]||(s[5]=[e("Moshe Zadka",-1)])]),_:1}),s[10]||(s[10]=e(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[e("geekpi",-1)])]),_:1}),s[12]||(s[12]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[e("Linux中國",-1)])]),_:1}),s[17]||(s[17]=e(" 榮譽推出",-1))])])}const C=o(u,[["render",f]]);export{x as __pageData,C as default};
